import csv, sys, os
D=os.path.expanduser('~/kinship-cases/komarova')
def load(n):
    with open(f'{D}/{n}',newline='',encoding='utf-8') as f: r=list(csv.DictReader(f)); return r
def save(n,rows):
    with open(f'{D}/{n}',newline='',encoding='utf-8') as f: hdr=next(csv.reader(f))
    with open(f'{D}/{n}','w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=hdr); w.writeheader(); w.writerows(rows)
def add(n,items):
    rows=load(n); rows+=items; save(n,rows)
